 foreach(var e in m.objects){var d=Read(e);Mesh mesh=e.kind=="Patch"?UnityEngine.Object.Instantiate(Find(s,e.name).sharedMesh):new Mesh();mesh.name=e.key;if(e.kind!="Patch"){mesh.indexFormat=IndexFormat.UInt32;mesh.vertices=d.positions;mesh.normals=d.normals;}foreach(var kv in d.uv)mesh.SetUVs(kv.Key,kv.Value);mesh.subMeshCount=d.indices.Length;for(int j=0;j<d.indices.Length;j++)mesh.SetTriangles(d.indices[j],j,false);mesh.RecalculateTangents();mesh.RecalculateBounds();Need(mesh.uv2.SequenceEqual(e.kind=="Patch"?Find(s,e.name).sharedMesh.uv2:new Vector2[0]),"Lightmap UV changed");AssetDatabase.CreateAsset(mesh,Output+"/Meshes/"+e.key+".asset");}
