 var colliders=roots.SelectMany(g=>g.GetComponentsInChildren<Collider>(true)).ToArray();string collision=HashObjects(colliders);var mc=roots.Single(g=>g.name=="MC00_ROOT_Standard_YUp_Frame");var mcComponents=mc.GetComponentsInChildren<Component>(true).Where(c=>c).Cast<UnityEngine.Object>().ToArray();string mcHash=HashObjects(mcComponents);var terrainComponents=roots.SelectMany(g=>g.GetComponentsInChildren<Terrain>(true)).Cast<UnityEngine.Object>().Concat(roots.SelectMany(g=>g.GetComponentsInChildren<TerrainCollider>(true))).ToArray();string terrainHash=HashObjects(terrainComponents);var originalComponents=roots.SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r!=renderer).Cast<UnityEngine.Object>().ToArray();string renderHash=HashObjects(originalComponents);var lightmaps=LightmapSettings.lightmaps.Select(l=>new[]{l.lightmapColor,l.lightmapDir,l.shadowMask}).ToArray();var probes=LightmapSettings.lightProbes;var oldActive=SceneManager.GetActiveScene();GameObject added=null;
